@app.route('/api/auth/change-password', methods=['POST'])
@token_required
@limiter.limit("5 per minute")
@limiter.limit("10 per hour")
def change_password():
    """Change user password - Unified for both platforms"""
    print("\n" + "="*60)
    print("[DEBUG] CHANGE PASSWORD ENDPOINT CALLED")
    print("="*60)
    
    try:
        data = request.get_json()
        user = g.current_user
        
        # Get platform info
        platform = getattr(g, 'platform', user.platform or 'platform_a')
        platform_config = PLATFORMS.get(platform, PLATFORMS['platform_a'])
        platform_name = platform_config.get('brand_name', 'AFDALNOVA')
        
        print(f"[DEBUG] User: {user.username} (ID: {user.id})")
        print(f"[DEBUG] Email: {user.email}")
        print(f"[DEBUG] Platform: {platform} ({platform_name})")
        print(f"[DEBUG] Request data: {data}")
        
        current_password = data.get('current_password')
        new_password = data.get('new_password')
        
        print(f"[DEBUG] Current password provided: {'Yes' if current_password else 'No'}")
        print(f"[DEBUG] New password provided: {'Yes' if new_password else 'No'}")
        
        if not current_password or not new_password:
            print("[DEBUG] ERROR: Missing password fields")
            return jsonify({
                'success': False, 
                'error': 'Current password and new password are required',
                'platform': platform,
                'platform_name': platform_name
            }), 400
        
        if len(new_password) < 6:
            print("[DEBUG] ERROR: New password too short")
            return jsonify({
                'success': False, 
                'error': 'New password must be at least 6 characters',
                'platform': platform,
                'platform_name': platform_name
            }), 400
        
        # Check current password
        print("[DEBUG] Checking current password...")
        password_valid = user.check_password(current_password)
        print(f"[DEBUG] Password valid: {password_valid}")
        
        if not password_valid:
            print("[DEBUG] ERROR: Current password incorrect")
            log_activity(user.id, 'change_password_failed', f'Incorrect current password on {platform_name}', request.remote_addr, platform)
            return jsonify({
                'success': False, 
                'error': 'Current password is incorrect',
                'platform': platform,
                'platform_name': platform_name
            }), 401
        
        # Prevent using same password
        if current_password == new_password:
            print("[DEBUG] ERROR: New password same as current")
            return jsonify({
                'success': False, 
                'error': 'New password must be different from current password',
                'platform': platform,
                'platform_name': platform_name
            }), 400
        
        # Update password
        print("[DEBUG] Setting new password...")
        user.set_password(new_password)
        user.updated_at = datetime.utcnow()
        db.session.commit()
        print("[DEBUG] Password changed successfully")
        
        # Log successful change
        log_activity(user.id, 'change_password', f'Password changed successfully on {platform_name}', request.remote_addr, platform)
        
        print("[DEBUG] CHANGE PASSWORD SUCCESS")
        print("="*60 + "\n")
        
        return jsonify({
            'success': True, 
            'message': f'Password changed successfully on {platform_name}. Use your new password to login.',
            'platform': platform,
            'platform_name': platform_name,
            'branding': {
                'name': platform_config.get('brand_name', platform_name),
                'primary_color': platform_config.get('primary_color', '#1A2A6C')
            }
        })
        
    except Exception as e:
        print(f"[DEBUG] EXCEPTION: {e}")
        import traceback
        traceback.print_exc()
        db.session.rollback()
        print("="*60 + "\n")
        return jsonify({
            'success': False, 
            'error': str(e)
        }), 500


@app.route('/api/user/change-password', methods=['POST'])
@token_required
@limiter.limit("5 per minute")
@limiter.limit("10 per hour")
def change_password_user():
    """Alias for change-password endpoint - Unified for both platforms"""
    print("\n" + "="*60)
    print("[DEBUG] CHANGE PASSWORD (USER ALIAS) CALLED")
    print(f"[DEBUG] Request path: {request.path}")
    print("="*60)
    return change_password()


@app.route('/api/auth/2fa/enable', methods=['POST'])
@token_required
@limiter.limit("3 per minute")
@limiter.limit("5 per hour")
def enable_2fa():
    """Enable 2FA for user"""
    try:
        import pyotp
        import base64
        from io import BytesIO
        
        # Generate secret
        secret = pyotp.random_base32()
        totp = pyotp.TOTP(secret)
        provisioning_uri = totp.provisioning_uri(g.current_user.email, issuer_name=COMPANY_NAME)
        
        # Generate QR code
        import qrcode
        qr = qrcode.QRCode(box_size=10, border=4)
        qr.add_data(provisioning_uri)
        qr.make(fit=True)
        
        img = qr.make_image(fill_color="black", back_color="white")
        
        # Convert to base64
        buffered = BytesIO()
        img.save(buffered, format="PNG")
        qr_code_base64 = base64.b64encode(buffered.getvalue()).decode()
        
        # Store secret temporarily (will be verified before saving)
        set_temp_data(f"2fa_temp:{g.current_user.id}", {
            'secret': secret,
            'expires': (datetime.utcnow() + timedelta(minutes=10)).isoformat()
        }, expiry_seconds=600)
        
        return jsonify({
            'success': True,
            'secret': secret,
            'qr_code': f"data:image/png;base64,{qr_code_base64}",
            'message': 'Scan the QR code with Google Authenticator or any TOTP app'
        })
        
    except Exception as e:
        print(f"Enable 2FA error: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/auth/2fa/verify', methods=['POST'])
@token_required
@limiter.limit("5 per minute")
@limiter.limit("10 per hour")
def verify_2fa_enable():
    """Verify and enable 2FA"""
    try:
        import pyotp
        
        data = request.get_json()
        code = data.get('code')
        
        if not code:
            return jsonify({'success': False, 'error': 'Verification code is required'}), 400
        
        # Get temporary secret
        temp_data = get_temp_data(f"2fa_temp:{g.current_user.id}")
        
        if not temp_data:
            return jsonify({'success': False, 'error': '2FA setup expired. Please try again.'}), 400
        
        secret = temp_data['secret']
        
        # Verify code
        totp = pyotp.TOTP(secret)
        if not totp.verify(code):
            # Log failed attempt
            log_activity(g.current_user.id, '2fa_verify_failed', 'Invalid 2FA code')
            return jsonify({'success': False, 'error': 'Invalid verification code'}), 400
        
        # Enable 2FA
        g.current_user.two_factor_secret = secret
        g.current_user.two_factor_enabled = True
        db.session.commit()
        
        # Clean up temp data
        delete_temp_data(f"2fa_temp:{g.current_user.id}")
        
        # Log success
        log_activity(g.current_user.id, '2fa_enabled', 'Two-factor authentication enabled')
        
        return jsonify({
            'success': True, 
            'message': f'2FA enabled successfully on {COMPANY_NAME}',
            'recovery_codes': generate_recovery_codes(g.current_user.id)  # Optional
        })
        
    except Exception as e:
        print(f"Verify 2FA error: {e}")
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/auth/2fa/disable', methods=['POST'])
@token_required
@limiter.limit("3 per minute")
@limiter.limit("5 per hour")
def disable_2fa():
    """Disable 2FA"""
    try:
        data = request.get_json()
        code = data.get('code')
        
        # Require 2FA code to disable (security)
        if g.current_user.two_factor_enabled:
            import pyotp
            totp = pyotp.TOTP(g.current_user.two_factor_secret)
            if not code or not totp.verify(code):
                return jsonify({'success': False, 'error': 'Valid 2FA code is required to disable'}), 401
        
        g.current_user.two_factor_enabled = False
        g.current_user.two_factor_secret = None
        db.session.commit()
        
        # Log activity
        log_activity(g.current_user.id, '2fa_disabled', 'Two-factor authentication disabled')
        
        return jsonify({
            'success': True, 
            'message': f'2FA disabled on {COMPANY_NAME}'
        })
        
    except Exception as e:
        print(f"Disable 2FA error: {e}")
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


# Optional: Helper function to generate recovery codes
def generate_recovery_codes(user_id):
    """Generate recovery codes for 2FA backup"""
    import secrets
    recovery_codes = []
    for _ in range(8):
        code = secrets.token_hex(4).upper()  # 8 character code
        recovery_codes.append(code)
        # Store in Redis or database
        set_temp_data(f"2fa_recovery:{user_id}:{code}", True, expiry_seconds=7776000)  # 90 days
    return recovery_codes

@app.route('/api/auth/sessions', methods=['GET'])
@token_required
@limiter.limit("30 per minute")
def get_sessions():
    """Get user's active sessions - Unified for both platforms"""
    try:
        user = g.current_user
        
        # Get platform info
        platform = getattr(g, 'platform', user.platform or 'platform_a')
        platform_config = PLATFORMS.get(platform, PLATFORMS['platform_a'])
        platform_name = platform_config.get('brand_name', 'AFDALNOVA')
        
        print(f"\n{'='*60}")
        print(f"[GET SESSIONS]")
        print(f"  User: {user.email}")
        print(f"  Platform: {platform} ({platform_name})")
        print(f"{'='*60}")
        
        # Get sessions from Redis instead of database for better performance
        session_key = f"user_sessions:{user.id}"
        sessions = get_temp_data(session_key)
        
        if not sessions:
            # Fallback to database
            sessions = UserSession.query.filter_by(
                user_id=user.id
            ).order_by(UserSession.created_at.desc()).limit(10).all()
            
            sessions_data = [{
                'id': s.id,
                'device': s.device_info,
                'ip_address': s.ip_address,
                'location': s.location,
                'platform': s.platform if hasattr(s, 'platform') else platform,
                'last_active': s.last_active.isoformat() if hasattr(s, 'last_active') and s.last_active else s.created_at.isoformat(),
                'is_current': s.id == getattr(g, 'current_session_id', None),
                'created_at': s.created_at.isoformat() if s.created_at else None
            } for s in sessions]
        else:
            sessions_data = sessions
        
        return jsonify({
            'success': True,
            'sessions': sessions_data,
            'total': len(sessions_data),
            'platform': platform,
            'platform_name': platform_name
        })
        
    except Exception as e:
        print(f"[GET SESSIONS ERROR] {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/auth/sessions/<int:session_id>', methods=['DELETE'])
@token_required
@limiter.limit("10 per minute")
@limiter.limit("30 per hour")
def revoke_session(session_id):
    """Revoke a user session - Unified for both platforms"""
    try:
        user = g.current_user
        
        # Get platform info
        platform = getattr(g, 'platform', user.platform or 'platform_a')
        platform_config = PLATFORMS.get(platform, PLATFORMS['platform_a'])
        platform_name = platform_config.get('brand_name', 'AFDALNOVA')
        
        print(f"\n{'='*60}")
        print(f"[REVOKE SESSION]")
        print(f"  User: {user.email}")
        print(f"  Session ID: {session_id}")
        print(f"  Platform: {platform} ({platform_name})")
        print(f"{'='*60}")
        
        # Check if session exists and belongs to user
        session = UserSession.query.filter_by(
            id=session_id, 
            user_id=user.id
        ).first()
        
        if not session:
            # Check Redis for active session
            session_key = f"session:{session_id}"
            session_data = get_temp_data(session_key)
            
            if session_data and session_data.get('user_id') == user.id:
                delete_temp_data(session_key)
                # Also remove from user's sessions list
                user_sessions_key = f"user_sessions:{user.id}"
                user_sessions = get_temp_data(user_sessions_key)
                if user_sessions:
                    user_sessions = [s for s in user_sessions if s.get('id') != session_id]
                    set_temp_data(user_sessions_key, user_sessions, 3600)
                
                # Log activity
                log_activity(user.id, 'session_revoked', f'Session {session_id} revoked on {platform_name}')
                
                return jsonify({
                    'success': True, 
                    'message': f'Session revoked successfully on {platform_name}',
                    'platform': platform,
                    'platform_name': platform_name
                })
            
            return jsonify({'success': False, 'error': 'Session not found'}), 404
        
        # Delete from database
        db.session.delete(session)
        db.session.commit()
        
        # Also remove from Redis if exists
        session_key = f"session:{session_id}"
        delete_temp_data(session_key)
        
        # Remove from user's sessions list
        user_sessions_key = f"user_sessions:{user.id}"
        user_sessions = get_temp_data(user_sessions_key)
        if user_sessions:
            user_sessions = [s for s in user_sessions if s.get('id') != session_id]
            set_temp_data(user_sessions_key, user_sessions, 3600)
        
        # Log activity
        log_activity(user.id, 'session_revoked', f'Session {session_id} revoked on {platform_name}')
        
        return jsonify({
            'success': True, 
            'message': f'Session revoked successfully on {platform_name}',
            'platform': platform,
            'platform_name': platform_name
        })
        
    except Exception as e:
        print(f"[REVOKE SESSION ERROR] {e}")
        import traceback
        traceback.print_exc()
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/auth/sessions/revoke-all', methods=['DELETE'])
@token_required
@limiter.limit("5 per minute")
@limiter.limit("10 per hour")
def revoke_all_sessions():
    """Revoke all user sessions except current - Unified for both platforms"""
    try:
        user = g.current_user
        
        # Get platform info
        platform = getattr(g, 'platform', user.platform or 'platform_a')
        platform_config = PLATFORMS.get(platform, PLATFORMS['platform_a'])
        platform_name = platform_config.get('brand_name', 'AFDALNOVA')
        
        print(f"\n{'='*60}")
        print(f"[REVOKE ALL SESSIONS]")
        print(f"  User: {user.email}")
        print(f"  Platform: {platform} ({platform_name})")
        print(f"{'='*60}")
        
        # Delete all sessions except current
        sessions = UserSession.query.filter_by(user_id=user.id).all()
        
        deleted_count = 0
        for session in sessions:
            if session.id != getattr(g, 'current_session_id', None):
                db.session.delete(session)
                deleted_count += 1
                
                # Also remove from Redis
                session_key = f"session:{session.id}"
                delete_temp_data(session_key)
        
        db.session.commit()
        
        # Clear user sessions from Redis
        user_sessions_key = f"user_sessions:{user.id}"
        delete_temp_data(user_sessions_key)
        
        # Log activity
        log_activity(user.id, 'all_sessions_revoked', f'Revoked {deleted_count} sessions on {platform_name}')
        
        return jsonify({
            'success': True,
            'message': f'Revoked {deleted_count} sessions on {platform_name}',
            'deleted_count': deleted_count,
            'platform': platform,
            'platform_name': platform_name
        })
        
    except Exception as e:
        print(f"[REVOKE ALL SESSIONS ERROR] {e}")
        import traceback
        traceback.print_exc()
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/auth/log-activity', methods=['POST'])
@token_required
@limiter.limit("60 per minute")
def log_activity_endpoint():
    """Log user activity - Unified for both platforms"""
    print("\n" + "="*60)
    print("[DEBUG] LOG ACTIVITY ENDPOINT CALLED")
    print("="*60)
    
    try:
        data = request.get_json() or {}
        user = g.current_user
        
        # Get platform info
        platform = getattr(g, 'platform', user.platform or 'platform_a')
        platform_config = PLATFORMS.get(platform, PLATFORMS['platform_a'])
        platform_name = platform_config.get('brand_name', 'AFDALNOVA')
        
        print(f"[DEBUG] User: {user.username} (ID: {user.id})")
        print(f"[DEBUG] Platform: {platform} ({platform_name})")
        print(f"[DEBUG] Request data: {data}")
        
        action = data.get('action')
        details = data.get('details')
        
        if not action:
            print("[DEBUG] No action provided - returning success")
            return jsonify({
                'success': True, 
                'message': 'No action provided',
                'platform': platform,
                'platform_name': platform_name
            })
        
        print(f"[DEBUG] Action: {action}")
        print(f"[DEBUG] Details: {details}")
        
        # Rate limit per action type
        try:
            action_key = f"activity:{user.id}:{action}"
            print(f"[DEBUG] Rate limit key: {action_key}")
            action_count = get_temp_data(action_key)
            
            if action_count:
                print("[DEBUG] Rate limited - skipping")
                return jsonify({
                    'success': True, 
                    'message': 'Activity logged (rate limited)',
                    'platform': platform,
                    'platform_name': platform_name
                })
            
            set_temp_data(action_key, 1, 1)
            print("[DEBUG] Rate limit set")
        except Exception as e:
            print(f"[DEBUG] Rate limiting error: {e}")
        
        # Log to database
        try:
            print("[DEBUG] Logging activity to database...")
            log_activity(user.id, action, details, request.remote_addr, platform)
            print("[DEBUG] Database log successful")
        except Exception as e:
            print(f"[DEBUG] Database log error: {e}")
        
        # Store recent activities in Redis
        try:
            print("[DEBUG] Storing in Redis...")
            recent_key = f"recent_activities:{user.id}"
            recent_activities = get_temp_data(recent_key) or []
            
            recent_activities.insert(0, {
                'action': action,
                'details': details,
                'platform': platform,
                'platform_name': platform_name,
                'timestamp': datetime.utcnow().isoformat()
            })
            
            recent_activities = recent_activities[:50]
            set_temp_data(recent_key, recent_activities, 86400)
            print("[DEBUG] Redis storage successful")
        except Exception as e:
            print(f"[DEBUG] Redis storage error: {e}")
        
        print("[DEBUG] LOG ACTIVITY SUCCESS")
        print("="*60 + "\n")
        return jsonify({
            'success': True,
            'platform': platform,
            'platform_name': platform_name
        })
        
    except Exception as e:
        print(f"[DEBUG] EXCEPTION: {e}")
        import traceback
        traceback.print_exc()
        print("="*60 + "\n")
        return jsonify({
            'success': True, 
            'message': 'Activity noted'
        })


def log_activity(user_id, action, details, ip_address=None, platform='platform_a'):
    """Log user activity to database - Platform aware"""
    print(f"[DEBUG log_activity] Called for user {user_id}, action: {action}, platform: {platform}")
    try:
        from models import UserSession
        activity = UserSession(
            user_id=user_id,
            action=action,
            details=details,
            ip_address=ip_address or request.remote_addr,
            platform=platform,
            created_at=datetime.utcnow()
        )
        db.session.add(activity)
        db.session.commit()
        print(f"[DEBUG log_activity] Successfully logged activity for user {user_id}")
    except Exception as e:
        print(f"[DEBUG log_activity] Error: {e}")
        db.session.rollback()
        # Don't raise, just print


@app.route('/api/auth/activities', methods=['GET'])
@token_required
@limiter.limit("30 per minute")
def get_user_activities():
    """Get user's recent activities - Unified for both platforms"""
    try:
        user = g.current_user
        
        # Get platform info
        platform = getattr(g, 'platform', user.platform or 'platform_a')
        platform_config = PLATFORMS.get(platform, PLATFORMS['platform_a'])
        platform_name = platform_config.get('brand_name', 'AFDALNOVA')
        
        page = request.args.get('page', 1, type=int)
        per_page = request.args.get('limit', 20, type=int)
        
        print(f"\n{'='*60}")
        print(f"[GET USER ACTIVITIES]")
        print(f"  User: {user.email}")
        print(f"  Platform: {platform} ({platform_name})")
        print(f"{'='*60}")
        
        # Try to get from Redis first
        recent_key = f"recent_activities:{user.id}"
        activities = get_temp_data(recent_key)
        
        if activities:
            # Filter by platform if needed
            if platform:
                activities = [a for a in activities if a.get('platform') == platform or not a.get('platform')]
            
            # Paginate Redis data
            start = (page - 1) * per_page
            end = start + per_page
            paginated = activities[start:end]
            
            return jsonify({
                'success': True,
                'activities': paginated,
                'total': len(activities),
                'page': page,
                'total_pages': (len(activities) + per_page - 1) // per_page,
                'platform': platform,
                'platform_name': platform_name
            })
        
        # Fallback to database
        # You would need a UserActivityLog model for this
        
        return jsonify({
            'success': True,
            'activities': [],
            'total': 0,
            'page': page,
            'total_pages': 0,
            'platform': platform,
            'platform_name': platform_name
        })
        
    except Exception as e:
        print(f"[GET ACTIVITIES ERROR] {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500


