@app.route('/order/<order_id>/retry', methods=['POST'])
@token_required
def retry_order(order_id):
    """Retry a failed order"""
    try:
        order = Order.query.filter_by(order_id=order_id, user_id=g.current_user.id).first()
        
        if not order:
            return jsonify({'success': False, 'error': 'Order not found'}), 404
        
        if order.delivery_status != 'failed':
            return jsonify({'success': False, 'error': 'Only failed orders can be retried'}), 400
        
        # Reset order status
        order.delivery_status = 'pending'
        order.delivery_attempts += 1
        order.last_delivery_error = None
        order.delivery_status_updated_at = datetime.utcnow()
        db.session.commit()
        
        # Retry Digimall delivery
        try:
            digimall = DigimallService()
            result = digimall.deliver_data(
                network=order.network,
                phone_number=order.phone_number,
                volume=order.size_gb
            )
            
            if result and result.get('success'):
                order.provider_order_id = result.get('orderId')
                order.provider_reference = result.get('reference')
                order.delivery_status = 'processing'
                db.session.commit()
                
                return jsonify({
                    'success': True,
                    'message': 'Order retried successfully',
                    'provider_order_id': result.get('orderId')
                })
            else:
                order.delivery_status = 'failed'
                order.last_delivery_error = result.get('error', 'Retry failed')
                db.session.commit()
                
                return jsonify({
                    'success': False,
                    'error': result.get('error', 'Retry failed')
                }), 400
                
        except Exception as e:
            order.delivery_status = 'failed'
            order.last_delivery_error = str(e)
            db.session.commit()
            return jsonify({'success': False, 'error': str(e)}), 500
        
    except Exception as e:
        print(f"Retry order error: {e}")
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/store/<slug>', methods=['GET'])
def get_public_store(slug):
    """Get public store data (no login required) - Filters unavailable packages"""
    try:
        from models import Store, User
        from sqlalchemy import text
        
        store = Store.query.filter_by(store_slug=slug, is_active=True).first()
        
        if not store:
            return jsonify({'success': False, 'error': 'Store not found'}), 404
        
        agent = User.query.get(store.agent_id)
        if not agent:
            return jsonify({'success': False, 'error': 'Store owner not found'}), 404
        
        # Get unavailable packages from database
        unavailable_packages = {}
        try:
            result = db.session.execute(text("""
                SELECT network, size_gb 
                FROM package_availability 
                WHERE is_available = FALSE
            """))
            for row in result:
                network = row[0]
                size_gb = str(int(row[1])) if float(row[1]).is_integer() else str(row[1])
                if network not in unavailable_packages:
                    unavailable_packages[network] = []
                unavailable_packages[network].append(size_gb)
            print(f"Unavailable packages filtered: {unavailable_packages}")
        except Exception as e:
            print(f"Error fetching unavailable packages: {e}")
        
        # Use the store's own markup (no StoreSettings needed)
        markup = store.markup if store.markup else 15
        
        # Get agent's wholesale prices - filter unavailable sizes
        agent_bundles = {}
        # Get all available sizes from price_settings first
        all_sizes = set()
        price_settings = PriceSetting.query.filter_by(category='agent_price', is_available=True).all()
        for setting in price_settings:
            if setting.network and setting.size_gb:
                all_sizes.add(setting.size_gb)
        
        # Sort sizes
        all_sizes = sorted(list(all_sizes))
        
        for network in ['mtn', 'telecel', 'airteltigo']:
            agent_bundles[network] = {}
            for size_gb in all_sizes:
                # Skip if this size is unavailable for this network
                size_str = str(size_gb)
                if size_str in unavailable_packages.get(network, []):
                    print(f"Skipping unavailable: {network} {size_gb}GB")
                    continue
                    
                price = get_agent_price(network, size_gb)
                if price > 0:
                    agent_bundles[network][size_gb] = price
        
        # Filter custom prices to remove unavailable sizes
        filtered_custom_prices = {}
        if store.custom_prices:
            for network, prices in store.custom_prices.items():
                filtered_custom_prices[network] = {}
                for size, price in prices.items():
                    size_str = str(size)
                    if size_str not in unavailable_packages.get(network, []):
                        filtered_custom_prices[network][size] = price
                    else:
                        print(f"Filtered out custom price: {network} {size}GB")
        
        return jsonify({
            'success': True,
            'data': {
                'store_name': store.store_name,
                'store_slug': store.store_slug,
                'store_description': store.store_description or '',
                'logo_url': store.logo_url,
                'banner_color': store.banner_color,
                'contact_phone': store.contact_phone or agent.phone,
                'contact_email': store.contact_email or agent.email,
                'markup': markup,
                'custom_prices': filtered_custom_prices,
                'agent_id': store.agent_id,
                'agent_name': agent.username if agent else None,
                'bundles': agent_bundles,
                'is_active': store.is_active
            }
        })
        
    except Exception as e:
        print(f"Get public store error: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/store/paystack-webhook', methods=['POST'])
def store_paystack_webhook():
    """Handle Paystack webhook for store payments"""
    try:
        payload = request.get_json()
        
        # Verify webhook signature
        signature = request.headers.get('x-paystack-signature')
        # Verify signature logic here (Paystack provides verification)
        
        event = payload.get('event')
        
        if event == 'charge.success':
            data = payload.get('data', {})
            reference = data.get('reference')
            amount = data.get('amount', 0) / 100  # Convert from pesewas
            fees = data.get('fees', 0) / 100  # Paystack fees
            net_amount = amount - fees  # What you actually receive
            
            # Find order by reference
            order = Order.query.filter_by(payment_reference=reference).first()
            if not order:
                return jsonify({'success': False, 'error': 'Order not found'}), 404
            
            # Check if already processed
            if order.status == 'completed':
                return jsonify({'success': True, 'message': 'Already processed'}), 200
            
            # Get agent
            agent = User.query.get(order.agent_id)
            
            # Calculate agent's share (selling price - wholesale price = profit)
            agent_earnings = order.profit  # This is the profit the agent makes
            
            # Deduct wholesale price from agent's wallet (they pay for the data)
            wholesale_price = order.cost
            if agent.wallet_balance >= wholesale_price:
                agent.wallet_balance -= wholesale_price
                
                # Credit agent's earnings (profit) to their wallet
                # This is their commission for the sale
                agent.wallet_balance += agent_earnings
                
                # Create transaction records
                # 1. Debit for wholesale cost
                debit_transaction = Transaction(
                    user_id=agent.id,
                    type='debit',
                    amount=wholesale_price,
                    balance_before=agent.wallet_balance - agent_earnings + wholesale_price,
                    balance_after=agent.wallet_balance - agent_earnings,
                    description=f'Store sale cost: {order.size_gb}GB {order.network} to {order.phone_number}',
                    reference=f"COST-{reference}",
                    status='completed'
                )
                db.session.add(debit_transaction)
                
                # 2. Credit for profit
                credit_transaction = Transaction(
                    user_id=agent.id,
                    type='credit',
                    amount=agent_earnings,
                    balance_before=agent.wallet_balance - agent_earnings,
                    balance_after=agent.wallet_balance,
                    description=f'Store sale earnings: {order.size_gb}GB {order.network}',
                    reference=f"EARN-{reference}",
                    status='completed'
                )
                db.session.add(credit_transaction)
                
                # Send data via Digimall
                try:
                    digimall = DigimallService()
                    digimall_result = digimall.deliver_data(
                        network=order.network,
                        phone_number=order.phone_number,
                        volume=order.size_gb
                    )
                    
                    if digimall_result and digimall_result.get('success'):
                        order.delivery_status = 'delivered'
                        order.status = 'completed'
                        order.completed_at = datetime.utcnow()
                        order.provider = 'digimall'
                        order.provider_order_id = digimall_result.get('orderId')
                    else:
                        order.delivery_status = 'failed'
                        order.last_delivery_error = digimall_result.get('error', 'Delivery failed')
                        # Refund the agent? Or handle appropriately
                except Exception as e:
                    print(f"Digimall error: {e}")
                    order.delivery_status = 'failed'
                    order.last_delivery_error = str(e)
            else:
                order.status = 'failed'
                order.last_delivery_error = 'Insufficient agent balance'
                # Notify agent to fund wallet
            
            db.session.commit()
        
        return jsonify({'success': True}), 200
        
    except Exception as e:
        print(f"Webhook error: {e}")
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500
    
