@app.route('/api/agent/store-earnings', methods=['GET'])
@token_required
@agent_required
def get_agent_store_earnings():
    """Get agent's earnings from store sales - AFDALNOVA"""
    try:
        from models import Store, Order
        
        # Get platform info
        platform = getattr(g, 'platform', 'platform_a')
        platform_config = PLATFORMS.get(platform, PLATFORMS['platform_a'])
        platform_name = platform_config.get('brand_name', 'AFDALNOVA')
        primary_color = platform_config.get('primary_color', '#1A2A6C')
        
        # Get store
        store = Store.query.filter_by(
            agent_id=g.current_user.id,
            platform=platform
        ).first()
        
        if not store:
            return jsonify({
                'success': True,
                'data': {
                    'total_sales': 0,
                    'total_earnings': 0,
                    'pending_payouts': 0,
                    'orders_count': 0,
                    'earnings_by_month': {},
                    'recent_orders': []
                },
                'platform': platform,
                'platform_name': platform_name
            })
        
        # Get all store orders
        orders = Order.query.filter_by(
            agent_id=g.current_user.id,
            platform=platform
        ).filter(
            Order.payment_method.in_(['paystack', 'store_pending', 'store_payment'])
        ).order_by(Order.created_at.desc()).all()
        
        # Calculate stats
        completed_orders = [o for o in orders if o.status == 'completed']
        total_sales = sum(o.amount for o in completed_orders)
        total_earnings = sum(o.profit for o in completed_orders)
        pending_payouts = sum(o.profit for o in orders if o.status == 'pending_payment')
        
        # Group by month
        earnings_by_month = {}
        for order in completed_orders:
            month_key = order.created_at.strftime('%Y-%m')
            earnings_by_month[month_key] = earnings_by_month.get(month_key, 0) + order.profit
        
        return jsonify({
            'success': True,
            'data': {
                'total_sales': float(total_sales),
                'total_earnings': float(total_earnings),
                'pending_payouts': float(pending_payouts),
                'orders_count': len(orders),
                'earnings_by_month': earnings_by_month,
                'recent_orders': [{
                    'order_id': o.order_id,
                    'amount': float(o.amount),
                    'earnings': float(o.profit),
                    'customer_phone': o.phone_number,
                    'product': f"{o.size_gb}GB {o.network}" if o.network else 'Data Bundle',
                    'created_at': o.created_at.isoformat(),
                    'status': o.status,
                    'platform': platform_name
                } for o in orders[:20]]
            },
            'platform': platform,
            'platform_name': platform_name,
            'branding': {
                'name': platform_config.get('brand_name', platform_name),
                'primary_color': primary_color,
                'secondary_color': platform_config.get('secondary_color', '#C9A84C')
            }
        })
        
    except Exception as e:
        print(f"[STORE EARNINGS ERROR] {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500


