@app.route('/api/agent/store/products', methods=['GET'])
@token_required
@agent_required
def get_agent_store_products():
    """Get products for agent's store with custom prices - AFDALNOVA"""
    try:
        agent_id = g.current_user.id
        
        # Get platform info
        platform = getattr(g, 'platform', 'platform_a')
        platform_config = get_platform_config(platform)
        platform_name = platform_config.get('brand_name', 'AFDALNOVA')
        primary_color = platform_config.get('primary_color', '#1A2A6C')
        
        print(f"[DEBUG] Getting products for agent: {agent_id} on {platform_name}")
        
        # Get agent's store settings
        store = Store.query.filter_by(agent_id=agent_id, platform=platform).first()
        print(f"[DEBUG] Store found: {store}")
        
        # Get base wholesale prices
        base_prices = {}
        for network in ['mtn', 'telecel', 'airteltigo']:
            base_prices[network] = {}
            for size_gb in [1, 2, 5, 10, 20]:
                price = get_agent_price(network, size_gb)
                if price > 0:
                    base_prices[network][size_gb] = price
        
        print(f"[DEBUG] Base prices: {base_prices}")
        
        # Safely get custom_prices and markup
        custom_prices = store.custom_prices if store and store.custom_prices else {}
        markup = store.markup if store and store.markup else 15
        
        products = []
        for network in ['mtn', 'telecel', 'airteltigo']:
            for size_gb, wholesale_price in base_prices.get(network, {}).items():
                # Get custom price or calculate with markup
                if custom_prices.get(network, {}).get(str(size_gb)):
                    selling_price = custom_prices[network][str(size_gb)]
                    is_custom = True
                else:
                    selling_price = wholesale_price * (1 + markup / 100)
                    is_custom = False
                
                products.append({
                    'id': f"{network}_{size_gb}",
                    'network': network,
                    'size_gb': size_gb,
                    'wholesale_price': wholesale_price,
                    'selling_price': round(selling_price, 2),
                    'profit': round(selling_price - wholesale_price, 2),
                    'custom_price': selling_price if is_custom else None,
                    'platform': platform_name
                })
        
        print(f"[DEBUG] Total products found: {len(products)}")
        
        return jsonify({
            'success': True,
            'data': {
                'products': products,
                'store': {
                    'store_name': store.store_name if store else None,
                    'store_slug': store.store_slug if store else None,
                    'markup': markup,
                    'custom_prices': custom_prices,
                    'banner_color': store.banner_color if store else primary_color,
                    'platform': platform_name
                }
            },
            'platform': platform,
            'platform_name': platform_name,
            'branding': {
                'name': platform_config.get('brand_name', platform_name),
                'primary_color': primary_color,
                'secondary_color': platform_config.get('secondary_color', '#C9A84C')
            }
        })
        
    except Exception as e:
        print(f"[ERROR] Get agent store products error: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/wallet/verify-payment', methods=['POST'])
@token_required
def verify_wallet_payment():
    """Verify manual payment and credit wallet - AFDALNOVA"""
    try:
        data = request.get_json()
        
        # Get platform info
        platform = getattr(g, 'platform', 'platform_a')
        platform_config = get_platform_config(platform)
        platform_name = platform_config.get('brand_name', 'AFDALNOVA')
        primary_color = platform_config.get('primary_color', '#1A2A6C')
        
        reference = data.get('reference')
        transaction_id = data.get('transaction_id')
        sender_name = data.get('sender_name')
        sender_phone = data.get('sender_phone')
        
        print(f"\n{'='*60}")
        print(f"VERIFY PAYMENT REQUEST - {platform_name}")
        print(f"{'='*60}")
        print(f"User: {g.current_user.username} (ID: {g.current_user.id})")
        print(f"Reference: {reference}")
        print(f"Transaction ID: {transaction_id}")
        print(f"Sender: {sender_name} / {sender_phone}")
        print(f"Platform: {platform_name}")
        
        if not reference or not transaction_id:
            return jsonify({
                'success': False, 
                'error': 'Reference and transaction ID are required',
                'platform': platform,
                'platform_name': platform_name
            }), 400
        
        # Find the manual payment request
        manual_payment = ManualPayment.query.filter_by(
            reference=reference.upper(),
            user_id=g.current_user.id,
            platform=platform
        ).first()
        
        if not manual_payment:
            return jsonify({
                'success': False, 
                'error': f'Payment request not found for reference: {reference} on {platform_name}',
                'platform': platform,
                'platform_name': platform_name
            }), 404
        
        if manual_payment.status != 'pending':
            return jsonify({
                'success': False, 
                'error': f'Payment already {manual_payment.status}',
                'platform': platform,
                'platform_name': platform_name
            }), 400
        
        # Update payment record
        manual_payment.status = 'verified'
        manual_payment.transaction_id = transaction_id
        manual_payment.sender_name = sender_name
        manual_payment.sender_phone = sender_phone
        manual_payment.verified_at = datetime.utcnow()
        manual_payment.verified_by = g.current_user.id
        manual_payment.notes = f'Verified via auto verification with transaction ID: {transaction_id} on {platform_name}'
        
        # Credit user's wallet
        old_balance = g.current_user.wallet_balance
        g.current_user.wallet_balance += manual_payment.amount
        
        # Create transaction record
        transaction = Transaction(
            user_id=g.current_user.id,
            type='credit',
            amount=manual_payment.amount,
            balance_before=old_balance,
            balance_after=g.current_user.wallet_balance,
            description=f'Manual payment verification - Ref: {reference} on {platform_name}',
            reference=reference,
            status='completed',
            platform=platform,
            meta_data={
                'payment_id': manual_payment.id,
                'transaction_id': transaction_id,
                'verification_method': 'auto'
            }
        )
        db.session.add(transaction)
        
        db.session.commit()
        
        print(f"✅ Payment verified! Credited ₵{manual_payment.amount} to {g.current_user.username} on {platform_name}")
        
        # Send confirmation email
        email_html = f"""
        <!DOCTYPE html>
        <html>
        <head>
            <style>
                body {{ font-family: 'Segoe UI', Arial, sans-serif; max-width: 600px; margin: 0 auto; background-color: #f5f7fa; }}
                .header {{ background: {primary_color}; padding: 30px; text-align: center; border-radius: 10px 10px 0 0; }}
                .header h1 {{ color: white; margin: 0; font-size: 24px; }}
                .header p {{ color: white; margin: 10px 0 0; opacity: 0.9; }}
                .content {{ background: white; padding: 30px; border-radius: 0 0 10px 10px; }}
                .info-box {{ background: #f8f9fa; padding: 15px; border-radius: 8px; margin: 15px 0; border-left: 4px solid {primary_color}; }}
                .footer {{ text-align: center; padding: 20px; background: #f8f9fa; color: #666; font-size: 12px; }}
            </style>
        </head>
        <body>
            <div class="header">
                <h1>💰 Payment Verified!</h1>
                <p>{platform_name}</p>
            </div>
            <div class="content">
                <p>Dear <strong>{g.current_user.username}</strong>,</p>
                <p>Your manual payment has been <strong style="color: #28a745;">VERIFIED</strong> and credited to your wallet.</p>
                <div class="info-box">
                    <h3 style="color: {primary_color};">📋 Payment Details:</h3>
                    <ul>
                        <li><strong>Amount:</strong> GHS {manual_payment.amount:.2f}</li>
                        <li><strong>Reference:</strong> {reference}</li>
                        <li><strong>Previous Balance:</strong> GHS {old_balance:.2f}</li>
                        <li><strong>New Balance:</strong> GHS {g.current_user.wallet_balance:.2f}</li>
                    </ul>
                </div>
                <p>Thank you for using {platform_name}!</p>
            </div>
            <div class="footer">
                <p>© 2025 {platform_name}. All rights reserved.</p>
                <p style="color: #C9A84C;">{platform_config.get('tagline', 'Innovation Meets Excellence')}</p>
            </div>
        </body>
        </html>
        """
        
        send_email(g.current_user.email, f"Payment Verified - {platform_name}", email_html, platform)
        
        return jsonify({
            'success': True,
            'message': f'Payment verified! ₵{manual_payment.amount:.2f} credited to your wallet on {platform_name}.',
            'data': {
                'amount': manual_payment.amount,
                'reference': reference,
                'transaction_id': transaction_id,
                'new_balance': g.current_user.wallet_balance,
                'platform': platform,
                'platform_name': platform_name,
                'branding': {
                    'name': platform_config.get('brand_name', platform_name),
                    'primary_color': primary_color,
                    'secondary_color': platform_config.get('secondary_color', '#C9A84C')
                }
            }
        })
        
    except Exception as e:
        print(f"[VERIFY WALLET PAYMENT ERROR] {e}")
        import traceback
        traceback.print_exc()
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/payment/verify-transfer', methods=['POST'])
@token_required
def verify_transfer_payment():
    """Verify mobile money transfer using Paystack Transfer API - AFDALNOVA"""
    try:
        data = request.get_json()
        
        # Get platform info
        platform = getattr(g, 'platform', 'platform_a')
        platform_config = get_platform_config(platform)
        platform_name = platform_config.get('brand_name', 'AFDALNOVA')
        primary_color = platform_config.get('primary_color', '#1A2A6C')
        
        reference = data.get('reference')
        transaction_id = data.get('transaction_id')
        amount = data.get('amount')
        sender_phone = data.get('sender_phone')
        
        print(f"\n{'='*80}")
        print(f"🔍 VERIFY TRANSFER PAYMENT - {platform_name}")
        print(f"{'='*80}")
        print(f"📱 User: {g.current_user.username} (ID: {g.current_user.id})")
        print(f"📧 Email: {g.current_user.email}")
        print(f"💰 Current Wallet Balance: ₵{g.current_user.wallet_balance}")
        print(f"📝 Reference: {reference}")
        print(f"🆔 Transaction ID: {transaction_id}")
        print(f"💵 Amount: ₵{amount}")
        print(f"📞 Sender Phone: {sender_phone}")
        print(f"📱 Platform: {platform_name}")
        print(f"{'='*80}\n")
        
        # Validate required fields
        if not reference or not transaction_id:
            print(f"❌ Validation failed: Missing reference or transaction_id")
            return jsonify({
                'success': False, 
                'error': 'Reference and transaction ID are required',
                'platform': platform,
                'platform_name': platform_name
            }), 400
        
        # Find the pending manual payment
        print(f"\n🔎 Searching for payment with reference: {reference.upper()}")
        manual_payment = ManualPayment.query.filter_by(
            reference=reference.upper(),
            user_id=g.current_user.id,
            platform=platform
        ).first()
        
        if not manual_payment:
            print(f"❌ No payment found with reference: {reference.upper()}")
            return jsonify({
                'success': False, 
                'error': f'Payment request not found for reference: {reference} on {platform_name}',
                'platform': platform,
                'platform_name': platform_name
            }), 404
        
        print(f"✅ Found payment: ID={manual_payment.id}, Status={manual_payment.status}, Amount=₵{manual_payment.amount}")
        
        if manual_payment.status != 'pending':
            print(f"❌ Payment status is '{manual_payment.status}', not 'pending'")
            return jsonify({
                'success': False, 
                'error': f'Payment already {manual_payment.status}',
                'platform': platform,
                'platform_name': platform_name
            }), 400
        
        # Get Paystack keys based on platform
        if platform == 'platform_a':
            paystack_secret = AFDALNOVA_PAYSTACK_SECRET_KEY
            paystack_public = AFDALNOVA_PAYSTACK_PUBLIC_KEY
        else:
            paystack_secret = ROAMSMART_PAYSTACK_SECRET_KEY
            paystack_public = ROAMSMART_PAYSTACK_PUBLIC_KEY
        
        headers = {
            'Authorization': f'Bearer {paystack_secret}',
            'Content-Type': 'application/json'
        }
        
        api_url = f'https://api.paystack.co/transfer/verify/{transaction_id}'
        print(f"📡 Requesting: {api_url}")
        print(f"🔑 Using {platform_name} Paystack keys")
        
        response = requests.get(
            api_url,
            headers=headers,
            timeout=30
        )
        
        print(f"📥 Response Status: {response.status_code}")
        
        if response.status_code == 200:
            result = response.json()
            print(f"📦 Response Body: {result}")
            
            if result.get('status'):
                transfer_data = result.get('data', {})
                transfer_status = transfer_data.get('status')
                transfer_amount = transfer_data.get('amount', 0) / 100
                transfer_reference = transfer_data.get('reference')
                
                print(f"\n💰 Transfer Details:")
                print(f"   Status: {transfer_status}")
                print(f"   Amount: ₵{transfer_amount}")
                print(f"   Reference: {transfer_reference}")
                print(f"   Platform: {platform_name}")
                
                if transfer_status != 'success':
                    print(f"❌ Transfer status is '{transfer_status}', not 'success'")
                    return jsonify({
                        'success': False, 
                        'error': f'Payment status: {transfer_status}. Please wait or contact support.',
                        'platform': platform,
                        'platform_name': platform_name
                    }), 400
                
                if amount:
                    user_amount = float(amount)
                    if abs(user_amount - transfer_amount) > 1:
                        print(f"❌ Amount mismatch: User entered ₵{user_amount}, Paystack shows ₵{transfer_amount}")
                        return jsonify({
                            'success': False,
                            'error': f'Amount mismatch. Paystack shows ₵{transfer_amount:.2f}, you entered ₵{user_amount:.2f}',
                            'platform': platform,
                            'platform_name': platform_name
                        }), 400
                    else:
                        print(f"✅ Amount verified: ₵{transfer_amount}")
                
                # Update payment record
                print(f"\n📝 Updating payment record...")
                manual_payment.status = 'verified'
                manual_payment.transaction_id = transaction_id
                manual_payment.sender_phone = sender_phone
                manual_payment.verified_at = datetime.utcnow()
                manual_payment.verified_by = 'paystack_api'
                manual_payment.amount = transfer_amount
                manual_payment.notes = f'Verified via Paystack API. Transaction ID: {transaction_id} on {platform_name}'
                
                # Credit wallet
                old_balance = g.current_user.wallet_balance
                print(f"💰 Crediting wallet: ₵{old_balance} + ₵{transfer_amount}")
                g.current_user.wallet_balance += transfer_amount
                
                # Create transaction record
                transaction = Transaction(
                    user_id=g.current_user.id,
                    type='credit',
                    amount=transfer_amount,
                    balance_before=old_balance,
                    balance_after=g.current_user.wallet_balance,
                    description=f'Mobile money payment verified - Ref: {reference} on {platform_name}',
                    reference=reference,
                    status='completed',
                    platform=platform,
                    meta_data={
                        'transaction_id': transaction_id,
                        'paystack_reference': transfer_reference,
                        'verification_method': 'paystack_transfer_api'
                    }
                )
                db.session.add(transaction)
                
                db.session.commit()
                
                print(f"\n✅ SUCCESS! Payment verified and credited on {platform_name}!")
                print(f"   Amount: ₵{transfer_amount}")
                print(f"   New Balance: ₵{g.current_user.wallet_balance}")
                print(f"{'='*80}\n")
                
                # Send confirmation email
                email_html = f"""
                <!DOCTYPE html>
                <html>
                <head>
                    <style>
                        body {{ font-family: 'Segoe UI', Arial, sans-serif; max-width: 600px; margin: 0 auto; background-color: #f5f7fa; }}
                        .header {{ background: {primary_color}; padding: 30px; text-align: center; border-radius: 10px 10px 0 0; }}
                        .header h1 {{ color: white; margin: 0; font-size: 24px; }}
                        .header p {{ color: white; margin: 10px 0 0; opacity: 0.9; }}
                        .content {{ background: white; padding: 30px; border-radius: 0 0 10px 10px; }}
                        .info-box {{ background: #f8f9fa; padding: 15px; border-radius: 8px; margin: 15px 0; border-left: 4px solid {primary_color}; }}
                        .footer {{ text-align: center; padding: 20px; background: #f8f9fa; color: #666; font-size: 12px; }}
                    </style>
                </head>
                <body>
                    <div class="header">
                        <h1>✅ Payment Verified!</h1>
                        <p>{platform_name}</p>
                    </div>
                    <div class="content">
                        <p>Dear <strong>{g.current_user.username}</strong>,</p>
                        <p>Your mobile money transfer has been <strong style="color: #28a745;">VERIFIED</strong> and credited to your wallet.</p>
                        <div class="info-box">
                            <h3 style="color: {primary_color};">📋 Payment Details:</h3>
                            <ul>
                                <li><strong>Amount:</strong> GHS {transfer_amount:.2f}</li>
                                <li><strong>Reference:</strong> {reference}</li>
                                <li><strong>Previous Balance:</strong> GHS {old_balance:.2f}</li>
                                <li><strong>New Balance:</strong> GHS {g.current_user.wallet_balance:.2f}</li>
                            </ul>
                        </div>
                        <p>Thank you for using {platform_name}!</p>
                    </div>
                    <div class="footer">
                        <p>© 2025 {platform_name}. All rights reserved.</p>
                        <p style="color: #C9A84C;">{platform_config.get('tagline', 'Innovation Meets Excellence')}</p>
                    </div>
                </body>
                </html>
                """
                
                send_email(g.current_user.email, f"Payment Verified - {platform_name}", email_html, platform)
                
                return jsonify({
                    'success': True,
                    'message': f'✅ Payment verified! ₵{transfer_amount:.2f} credited to your wallet on {platform_name}.',
                    'data': {
                        'amount': transfer_amount,
                        'reference': reference,
                        'transaction_id': transaction_id,
                        'new_balance': g.current_user.wallet_balance,
                        'paystack_status': transfer_status,
                        'platform': platform,
                        'platform_name': platform_name,
                        'branding': {
                            'name': platform_config.get('brand_name', platform_name),
                            'primary_color': primary_color,
                            'secondary_color': platform_config.get('secondary_color', '#C9A84C')
                        }
                    }
                })
        else:
            print(f"❌ Paystack API request failed with status {response.status_code}")
            print(f"   Response: {response.text[:500]}")
        
        print(f"\n❌ VERIFICATION FAILED - Unable to verify payment with Paystack on {platform_name}")
        print(f"{'='*80}\n")
        
        return jsonify({
            'success': False,
            'error': f'Unable to verify payment on {platform_name}. Please check your transaction ID and try again, or contact support.',
            'platform': platform,
            'platform_name': platform_name
        }), 400
        
    except Exception as e:
        print(f"\n❌ EXCEPTION in verify_transfer_payment on {platform_name}:")
        print(f"   Error: {str(e)}")
        import traceback
        traceback.print_exc()
        print(f"{'='*80}\n")
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500
    
@app.route('/api/payment/manual-with-paystack-verify', methods=['POST'])
@token_required
def manual_payment_with_paystack_verify():
    """
    User makes manual payment, then verifies using Paystack reference
    """
    try:
        data = request.get_json()
        paystack_reference = data.get('paystack_reference')
        amount = data.get('amount')
        phone = data.get('phone')
        
        if not paystack_reference:
            return jsonify({'success': False, 'error': 'Paystack reference is required'}), 400
        
        # 1. Verify the payment with Paystack API
        headers = {
            'Authorization': f'Bearer {current_app.config["PAYSTACK_SECRET_KEY"]}'
        }
        
        response = requests.get(
            f'https://api.paystack.co/transaction/verify/{paystack_reference}',
            headers=headers,
            timeout=30
        )
        
        if response.status_code != 200:
            return jsonify({'success': False, 'error': 'Failed to verify payment with Paystack'}), 400
        
        paystack_data = response.json()
        
        if not paystack_data.get('status'):
            return jsonify({'success': False, 'error': 'Invalid Paystack reference'}), 400
        
        transaction_data = paystack_data.get('data', {})
        
        # Check if payment was successful
        if transaction_data.get('status') != 'success':
            return jsonify({
                'success': False, 
                'error': f'Payment not successful. Status: {transaction_data.get("status")}'
            }), 400
        
        # Get payment details from Paystack
        paystack_amount = transaction_data.get('amount', 0) / 100  # Convert from kobo/pesewas
        paystack_currency = transaction_data.get('currency', 'GHS')
        paystack_customer_email = transaction_data.get('customer', {}).get('email')
        
        # 2. Check if this reference has already been used
        existing = ManualPayment.query.filter_by(paystack_reference=paystack_reference).first()
        if existing:
            return jsonify({'success': False, 'error': 'This reference has already been verified'}), 400
        
        # 3. Validate amount matches (optional - with tolerance)
        if amount:
            user_amount = float(amount)
            if abs(user_amount - paystack_amount) > 1:  # 1 GHS tolerance
                return jsonify({
                    'success': False, 
                    'error': f'Amount mismatch. Paystack shows ₵{paystack_amount:.2f}, you entered ₵{user_amount:.2f}'
                }), 400
        
        # 4. Create manual payment record
        manual_payment = ManualPayment(
            user_id=g.current_user.id,
            paystack_reference=paystack_reference,
            amount=paystack_amount,
            phone=phone or g.current_user.phone,
            status='verified',  # Auto-verified!
            payment_method='paystack_manual',
            customer_email=paystack_customer_email,
            paystack_data=transaction_data,
            verified_at=datetime.utcnow(),
            verified_by='system',
            created_at=datetime.utcnow()
        )
        db.session.add(manual_payment)
        
        # 5. Credit user's wallet
        old_balance = g.current_user.wallet_balance
        g.current_user.wallet_balance += paystack_amount
        
        # Create transaction record
        transaction = Transaction(
            user_id=g.current_user.id,
            type='deposit',
            amount=paystack_amount,
            balance_before=old_balance,
            balance_after=g.current_user.wallet_balance,
            description=f'Paystack manual payment verification - Ref: {paystack_reference}',
            reference=paystack_reference,
            status='completed',
            payment_method='paystack_manual'
        )
        db.session.add(transaction)
        
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': f'Payment verified! ₵{paystack_amount:.2f} credited to your wallet.',
            'data': {
                'amount': paystack_amount,
                'reference': paystack_reference,
                'new_balance': g.current_user.wallet_balance,
                'paystack_status': transaction_data.get('status'),
                'paystack_channel': transaction_data.get('channel')
            }
        })
        
    except Exception as e:
        print(f"Manual payment with Paystack verify error: {e}")
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/agent/store/products/update-price', methods=['POST'])
@token_required
@agent_required
def update_agent_product_price():
    """Update a single product's custom price in agent's store"""
    try:
        data = request.get_json()
        network = data.get('network')
        size_gb = data.get('size_gb')
        custom_price = data.get('custom_price')
        
        if not network or not size_gb:
            return jsonify({'success': False, 'error': 'Network and size are required'}), 400
        
        # Get agent's store
        store = Store.query.filter_by(agent_id=g.current_user.id).first()
        if not store:
            return jsonify({'success': False, 'error': 'Store not found. Please set up your store first.'}), 404
        
        # Initialize custom_prices dict if not exists
        if not store.custom_prices:
            store.custom_prices = {}
        
        if network not in store.custom_prices:
            store.custom_prices[network] = {}
        
        # Update or remove custom price
        if custom_price and custom_price > 0:
            store.custom_prices[network][str(size_gb)] = custom_price
        else:
            # Remove custom price if exists (use default markup)
            if network in store.custom_prices and str(size_gb) in store.custom_prices[network]:
                del store.custom_prices[network][str(size_gb)]
        
        store.updated_at = datetime.utcnow()
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': f'Price for {network.upper()} {size_gb}GB updated successfully',
            'data': {
                'network': network,
                'size_gb': size_gb,
                'custom_price': custom_price if custom_price > 0 else None
            }
        })
        
    except Exception as e:
        print(f"Update product price error: {e}")
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/agent/store/products/bulk-update', methods=['POST'])
@token_required
@agent_required
def bulk_update_agent_prices():
    """Bulk update multiple product prices"""
    try:
        data = request.get_json()
        products = data.get('products', [])
        default_markup = data.get('default_markup')
        
        # Get agent's store
        store = Store.query.filter_by(agent_id=g.current_user.id).first()
        if not store:
            return jsonify({'success': False, 'error': 'Store not found. Please set up your store first.'}), 404
        
        # Update default markup if provided
        if default_markup is not None:
            store.markup = default_markup
        
        # Initialize custom_prices dict if not exists
        if not store.custom_prices:
            store.custom_prices = {}
        
        # Update individual product prices
        for product in products:
            network = product.get('network')
            size_gb = product.get('size_gb')
            custom_price = product.get('custom_price')
            
            if network and size_gb:
                if network not in store.custom_prices:
                    store.custom_prices[network] = {}
                
                if custom_price and custom_price > 0:
                    store.custom_prices[network][str(size_gb)] = custom_price
                else:
                    if network in store.custom_prices and str(size_gb) in store.custom_prices[network]:
                        del store.custom_prices[network][str(size_gb)]
        
        store.updated_at = datetime.utcnow()
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': f'Updated {len(products)} products and markup successfully',
            'data': {
                'markup': store.markup,
                'updated_products': len(products)
            }
        })
        
    except Exception as e:
        print(f"Bulk update prices error: {e}")
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


