# ========== ERROR HANDLERS ==========

@app.errorhandler(404)
def not_found(error):
    return jsonify({
        'error': 'Not found', 
        'message': f'The requested endpoint does not exist on {COMPANY_NAME}',
        'status_code': 404
    }), 404


@app.errorhandler(500)
def internal_error(error):
    return jsonify({
        'error': 'Internal server error', 
        'message': f'Something went wrong on {COMPANY_NAME}. Please try again later.',
        'status_code': 500
    }), 500


@app.errorhandler(429)
def rate_limit_error(error):
    return jsonify({
        'error': 'Rate limit exceeded',
        'message': f'Too many requests on {COMPANY_NAME}. Please try again later.',
        'status_code': 429
    }), 429


@app.errorhandler(401)
def unauthorized_error(error):
    return jsonify({
        'error': 'Unauthorized',
        'message': f'Authentication required to access this resource on {COMPANY_NAME}',
        'status_code': 401
    }), 401


@app.errorhandler(403)
def forbidden_error(error):
    return jsonify({
        'error': 'Forbidden',
        'message': f'You do not have permission to access this resource on {COMPANY_NAME}',
        'status_code': 403
    }), 403


@app.errorhandler(SQLAlchemyError)
def handle_db_error(error):
    """Handle database errors gracefully"""
    print(f"Database error: {error}")
    db.session.rollback()
    return jsonify({
        'success': False,
        'error': 'A system error occurred. Please try again later.'
    }), 500

@app.errorhandler(IntegrityError)
def handle_integrity_error(error):
    """Handle database integrity errors"""
    print(f"Integrity error: {error}")
    db.session.rollback()
    return jsonify({
        'success': False,
        'error': 'Invalid data submitted. Please check your input.'
    }), 400

@app.errorhandler(DataError)
def handle_data_error(error):
    """Handle data type errors (like VARCHAR truncation)"""
    print(f"Data error: {error}")
    db.session.rollback()
    return jsonify({
        'success': False,
        'error': 'The data you entered is too long. Please shorten your input.'
    }), 400

@app.errorhandler(500)
def handle_500_error(error):
    """Handle unexpected 500 errors"""
    print(f"500 error: {error}")
    return jsonify({
        'success': False,
        'error': 'Something went wrong. Our team has been notified.'
    }), 500

@app.errorhandler(Exception)
def handle_generic_error(error):
    """Handle any unhandled exceptions"""
    print(f"Unhandled error: {error}")
    import traceback
    traceback.print_exc()
    return jsonify({
        'success': False,
        'error': 'An unexpected error occurred. Please try again.'
    }), 500

